mapper.select:
SELECT id AS id, ctg_path AS ctgPath, white_paper_code AS whitePaperCode, wp_name AS wpName, wp_type AS wpType, wp_owner AS wpOwner, wp_level AS wpLevel, last_visit_time AS lastVisitTime, days_no_visit AS daysNoVisit FROM ssm_governance_field_label
WHERE id > #{lastId}
ORDER BY id LIMIT #{pageSize}

mapper.update:
UPDATE ssm_governance_field_task
status = #{status}, notice_time = #{noticeTime}, last_notice_time = #{lastNoticeTime}, notice_count = #{noticeCount}, exempt_time = #{exemptTime}, exempt_expire_date = #{exemptExpireDate}, updated_time = now()
WHERE id = #{id}
